export type Invoice = {
  id: string
  name: string
  amount: number
}

export type MonthlyRevenue = {
  month: string
  amount: number
}

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: MonthlyRevenue[]
  invoices: Invoice[]
}

// Identical fetch calls are memoized for the request, so each streamed
// section can read the dashboard without starting another network call.
export async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')

  if (!res.ok) {
    throw new Error(`Failed to load dashboard: ${res.status}`)
  }

  return res.json()
}

