import { getDashboardData } from './data'

export function CardStats({
  totalRevenue,
  totalInvoices,
}: {
  totalRevenue: React.ReactNode
  totalInvoices: React.ReactNode
}) {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>{totalRevenue}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

export async function TotalRevenueValue() {
  const data = await getDashboardData()
  return <>${data.totalRevenue.toLocaleString()}</>
}

export async function TotalInvoicesValue() {
  const data = await getDashboardData()
  return <>{data.totalInvoices}</>
}

