import { Suspense } from 'react'
import {
  CardStats,
  TotalInvoicesValue,
  TotalRevenueValue,
} from './CardStats'
import { LatestInvoices, LatestInvoicesData } from './LatestInvoices'
import { RevenueChart, RevenueChartData } from './RevenueChart'

function ValueFallback() {
  return (
    <span className="loading">
      <span className="spinner" />
    </span>
  )
}

function ListFallback() {
  return (
    <ul className="loading" aria-hidden="true">
      <li>
        <span className="spinner" />
      </li>
    </ul>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <CardStats
        totalRevenue={
          <Suspense fallback={<ValueFallback />}>
            <TotalRevenueValue />
          </Suspense>
        }
        totalInvoices={
          <Suspense fallback={<ValueFallback />}>
            <TotalInvoicesValue />
          </Suspense>
        }
      />
      <RevenueChart
        revenue={
          <Suspense fallback={<ListFallback />}>
            <RevenueChartData />
          </Suspense>
        }
      />
      <LatestInvoices
        invoices={
          <Suspense fallback={<ListFallback />}>
            <LatestInvoicesData />
          </Suspense>
        }
      />
    </main>
  )
}

